import { withBase } from "ufo";
import { pascalCase } from "scule";
import { toHast } from "minimark/hast";
import manifest from "#content/manifest";
const linkProps = ["href", "src", "to"];
export function getDefaultLocale(collection) {
  return manifest[collection]?.i18n?.defaultLocale;
}
export function localizePath(path, collection, locale, raw = false) {
  const i18n = manifest[collection]?.i18n;
  if (!i18n || !locale) {
    return path;
  }
  const prefixed = locale !== i18n.defaultLocale || raw && i18n.locales.includes(path.split("/")[1] || "");
  return prefixed ? `/${locale}${path === "/" ? "" : path}` : path;
}
export async function createDocumentGenerator() {
  const { visit } = await import("unist-util-visit");
  const { stringifyMarkdown } = await import("@nuxtjs/mdc/runtime");
  return generateDocument;
  async function generateDocument(doc, options) {
    const hastTree = refineDocumentBody(doc.body, options);
    let markdown = await stringifyMarkdown(hastTree, {});
    if (!markdown?.trim().startsWith("# ")) {
      const title = doc.title || doc.seo?.title || "";
      if (title) {
        markdown = `# ${title}

${markdown}`;
      }
    }
    return markdown;
  }
  function refineDocumentBody(body, options) {
    const hastTree = toHast(body);
    visit(hastTree, (node) => {
      const el = node;
      if (!el.props?.to && !el.props?.href && !el.props?.src) {
        return;
      }
      for (const prop of linkProps) {
        if (el.props?.[prop]) {
          el.props[prop] = withBase(el.props[prop], options.domain);
        }
      }
    });
    return hastTree;
  }
}
export function prepareContentSections(sections) {
  const contentSections = sections.filter((section) => section.contentCollection);
  if (contentSections.length) {
    return;
  }
  const pageCollecitons = Object.keys(manifest).filter((c) => manifest[c].type === "page");
  const autoGeneratedSections = pageCollecitons.map((c) => ({
    __nuxt_content_auto_generate: true,
    title: pascalCase(c),
    contentCollection: c,
    contentFilters: [
      {
        field: "extension",
        operator: "=",
        value: "md"
      }
    ]
  }));
  sections.push(...autoGeneratedSections);
}
